/***
A dark generative waterfall made from glowing particle streams, neural geometry, and atmospheric mist.
Click to create splash 


created for "Waterfall" 🚿 #WCCChallenge
***/

let drops = [];
let veil = [];
let mist = [];
let links = [];

const DROP_COUNT = 360;
const VEIL_COUNT = 900;
const MIST_COUNT = 260;

const CHANNELS = [-260, -90, 70, 230];

function setup() {
  createCanvas(windowWidth, windowHeight);

  pixelDensity(1);

  colorMode(HSB, 360, 100, 100, 100);

  background(220, 70, 3);

  strokeCap(ROUND);

  for (let i = 0; i < DROP_COUNT; i++) {
    drops.push(new Drop());
  }

  for (let i = 0; i < VEIL_COUNT; i++) {
    veil.push(new VeilStrand());
  }

  for (let i = 0; i < MIST_COUNT; i++) {
    mist.push(new Mist());
  }
}

function draw() {

  background(220, 70, 3, 14);

  drawDarkVignette();

  // veil
  for (let v of veil) {
    v.update();
    v.display();
  }

  // glow
  drawBlueMistGlow();

  // water 
  drawSoftWaterSheets();

  drawingContext.shadowBlur = 14;
  drawingContext.shadowColor = "#78eaff";

  // water streams
  for (let d of drops) {
    d.update();
    d.display();
  }

  drawNeuralLinks();

  drawingContext.shadowBlur = 0;

  // floating fog
  for (let m of mist) {
    m.update();
    m.display();
  }

  drawBottomFog();
}

class Drop {

  constructor() {
    this.reset(true);
  }

  reset(first = false) {

    this.channel = random(CHANNELS);

    this.x =
      width / 2 +
      this.channel +
      random(-50, 50);

    this.y =
      first
        ? random(-height, height)
        : random(-350, -20);

    this.prevX = this.x;
    this.prevY = this.y;

    this.vx = random(-0.15, 0.15);
    this.vy = random(4, 8);

    this.size = random(0.9, 2.8);

    this.hue = random(188, 198);

    this.life = random(100, 250);
    this.age = 0;
  }

  update() {

    this.prevX = this.x;
    this.prevY = this.y;

    let center =
      width / 2 + this.channel;

    let n =
      noise(
        this.x * 0.005,
        this.y * 0.004,
        frameCount * 0.006
      );

    let drift =
      map(n, 0, 1, -0.45, 0.45);

    this.vx +=
      (center - this.x) * 0.0015 +
      drift * 0.045;

    this.vy += 0.075;

    if (random() < 0.012) {
      this.vx += random(-0.7, 0.7);
    }

    this.vx *= 0.94;
    this.vy *= 0.998;

    this.x += this.vx;
    this.y += this.vy;

    this.age++;

    if (frameCount % 2 === 0) {

      links.push({
        x: this.x,
        y: this.y,
        life: 50
      });

      if (links.length > 340) {
        links.shift();
      }
    }

    if (
      this.y > height + 90 ||
      this.age > this.life
    ) {
      this.reset();
    }
  }

  display() {

    stroke(this.hue, 55, 100, 25);

    strokeWeight(this.size * 0.45);

    line(
      this.prevX,
      this.prevY,
      this.x,
      this.y
    );

    noStroke();

    fill(this.hue, 55, 100, 78);

    ellipse(
      this.x,
      this.y,
      this.size * 0.7,
      this.size * 7.5
    );

    fill(this.hue, 20, 100, 12);

    ellipse(
      this.x,
      this.y + this.size * 2,
      this.size * 2.6,
      this.size * 13
    );
  }
}

class VeilStrand {

  constructor() {
    this.reset(true);
  }

  reset(first = false) {

    this.x =
      random(width * 0.04, width * 0.96);

    this.y =
      first
        ? random(-height, height)
        : random(-height * 0.7, 0);

    this.len =
      random(height * 0.65, height * 1.25);

    this.speed =
      random(0.25, 0.9);

    this.weight =
      random(0.28, 1.4);

    this.alpha =
      random(10, 28);

    this.hue =
      random(335, 355);

    this.sat =
      random(35, 55);

    this.bri =
      random(45, 70);

    this.offset =
      random(TWO_PI);

    this.wave =
      random(12, 55);
  }

  update() {

    this.y += this.speed;

    if (this.y > height + 120) {

      this.reset();

      this.y =
        random(-height * 0.9, -120);
    }
  }

  display() {

    noFill();

    stroke(
      this.hue,
      this.sat,
      this.bri,
      this.alpha
    );

    strokeWeight(this.weight);

    beginShape();

    for (let i = 0; i < 11; i++) {

      let t = i / 10;

      let yy =
        this.y + t * this.len;

      let xx =
        this.x +
        sin(
          t * TWO_PI +
          this.offset +
          frameCount * 0.004
        ) * this.wave +
        noise(
          this.x * 0.004,
          yy * 0.003,
          frameCount * 0.001
        ) * 26;

      curveVertex(xx, yy);
    }

    endShape();
  }
}

class Mist {

  constructor() {
    this.reset(true);
  }

  reset(first = false) {

    this.x = random(width);

    this.y =
      first
        ? random(height * 0.65, height)
        : random(height * 0.82, height + 100);

    this.r =
      random(4, 32);

    this.vx =
      random(-0.35, 0.35);

    this.vy =
      random(-0.3, -0.04);

    this.alpha =
      random(4, 18);

    this.hue =
      random(335, 355);
  }

  update() {

    this.x +=
      this.vx +
      sin(frameCount * 0.01 + this.y * 0.01) * 0.12;

    this.y += this.vy;

    if (
      this.y < height * 0.55 ||
      this.x < -60 ||
      this.x > width + 60
    ) {
      this.reset();
    }
  }

  display() {

    noStroke();

    fill(
      this.hue,
      35,
      80,
      this.alpha
    );

    circle(
      this.x,
      this.y,
      this.r
    );
  }
}

function drawBlueMistGlow() {

  noStroke();

  for (let c of CHANNELS) {

    // LARGE CYAN VAPOR
    for (let i = 0; i < 14; i++) {

      let x =
        width / 2 +
        c +
        random(-55, 55);

      let y =
        map(i, 0, 13, 0, height);

      let w =
        random(40, 120);

      let h =
        random(140, 260);

      fill(190, 35, 100, 1.8);

      ellipse(x, y, w, h);
    }

    // stream glow
    for (let i = 0; i < 24; i++) {

      var x =
        width / 2 +
        c +
        random(-35, 35);

      var y = random(height);

      fill(195, 40, 100, 2.8);

      ellipse(
        x,
        y,
        random(18, 55),
        random(40, 140)
      );
    }
  }
}

function drawSoftWaterSheets() {

  noFill();

  for (let c of CHANNELS) {

    for (let i = 0; i < 9; i++) {

      var x =
        width / 2 +
        c +
        random(-45, 45);

      stroke(195, 35, 90, 8);

      strokeWeight(
        random(1.2, 4)
      );

      beginShape();

      curveVertex(x, -160);

      for (
        var y = -100;
        y <= height + 120;
        y += 120
      ) {

        let wave =
          sin(
            y * 0.006 +
            frameCount * 0.008 +
            i
          ) * 22 +
          noise(
            i * 0.2,
            y * 0.003,
            frameCount * 0.002
          ) * 35;

        curveVertex(x + wave, y);
      }

      curveVertex(x, height + 180);

      endShape();
    }
  }
}

function drawNeuralLinks() {

  for (let i = links.length - 1; i >= 0; i--) {

    links[i].life--;

    if (links[i].life <= 0) {
      links.splice(i, 1);
    }
  }

  for (let i = 0; i < links.length; i += 10) {

    let a = links[i];

    for (
      let j = i + 12;
      j < links.length;
      j += 24
    ) {

      let b = links[j];

      let d =
        dist(a.x, a.y, b.x, b.y);

      if (d < 145) {

        let alpha =
          map(d, 0, 145, 18, 0);

        stroke(190, 55, 100, alpha);

        strokeWeight(0.55);

        line(a.x, a.y, b.x, b.y);
      }
    }
  }
}

function drawBottomFog() {

  noStroke();

  for (let i = 0; i < 130; i++) {

    var x = random(width);

    var y =
      height * 0.78 +
      random(height * 0.22);

    let r =
      random(8, 55);

    if (random() < 0.55) {
      fill(190, 15, 95, 3);
    } else {
      fill(340, 30, 80, 5);
    }

    circle(x, y, r);
  }
}

function drawDarkVignette() {

  noStroke();

  fill(220, 80, 2, 40);

  rect(0, 0, width, height);

  fill(220, 80, 1, 24);

  rect(0, 0, width * 0.08, height);

  rect(
    width * 0.92,
    0,
    width * 0.08,
    height
  );
}

function mousePressed() {
  for (let i = 0; i < 18; i++) {
    var d = new Drop();

    d.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-45, 45);
    d.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-45, 45);
    d.vx = random(-2.5, 2.5);
    d.vy = random(2, 7);

    drops.push(d);
  }

  while (drops.length > DROP_COUNT + 80) {
    drops.shift();
  }
}

function keyPressed() {

  if (key === "s" || key === "S") {
    saveCanvas(
      "neural-waterfall-blue-mist",
      "png"
    );
  }

  if (key === "r" || key === "R") {

    drops = [];
    veil = [];
    mist = [];
    links = [];

    for (let i = 0; i < DROP_COUNT; i++) {
      drops.push(new Drop());
    }

    for (let i = 0; i < VEIL_COUNT; i++) {
      veil.push(new VeilStrand());
    }

    for (let i = 0; i < MIST_COUNT; i++) {
      mist.push(new Mist());
    }

    background(220, 70, 3);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

